from solution import add_elements
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref(arr, k):
    # Obviously-correct model: at most two digits <=> abs value <= 99
    # (single digit 0-9, two digits 10-99, same for negatives ignoring sign)
    return sum(x for x in arr[:k] if abs(x) <= 99)


# ---- concrete example from spec ----

def test_example_from_spec():
    assert add_elements([111, 21, 3, 4000, 5, 6, 7, 8, 9], 4) == 24


# ---- explicit boundary examples ----

def test_single_digit_positive_included():
    assert add_elements([5], 1) == 5


def test_zero_has_one_digit():
    assert add_elements([0], 1) == 0


def test_two_digits_upper_bound_included():
    assert add_elements([99], 1) == 99
    assert add_elements([10], 1) == 10


def test_three_digits_lower_bound_excluded():
    assert add_elements([100], 1) == 0
    assert add_elements([111], 1) == 0
    assert add_elements([4000], 1) == 0


def test_negative_single_digit_included():
    assert add_elements([-5], 1) == -5
    assert add_elements([-9], 1) == -9
    assert add_elements([0, -1], 2) == -1


def test_negative_two_digits_included():
    assert add_elements([-10], 1) == -10
    assert add_elements([-21], 1) == -21
    assert add_elements([-99], 1) == -99


def test_negative_three_digits_excluded():
    # -100 has three digits ignoring sign, must be excluded
    assert add_elements([-100], 1) == 0


def test_negative_three_digits_excluded_range():
    # every value in [-999, -100] has 3 digits -> excluded
    assert add_elements([-100, -101, -123, -999], 4) == 0


def test_negative_four_digits_excluded():
    assert add_elements([-1000], 1) == 0
    assert add_elements([-4000], 1) == 0


def test_mixed_sign_two_digit_sum():
    # -21 (2 digits) + 3 (1 digit), 111 excluded
    assert add_elements([111, -21, 3], 3) == -18


def test_only_first_k_considered():
    assert add_elements([1, 2, 3, 100], 3) == 6
    assert add_elements([100, 1, 2], 1) == 0
    assert add_elements([100, 1, 2], 2) == 1


def test_k_equals_len():
    assert add_elements([111, 21, 3, 4000], 4) == 24


def test_k_equals_one():
    assert add_elements([21, 1000], 1) == 21
    assert add_elements([1000, 21], 1) == 0


def test_all_excluded_gives_zero():
    assert add_elements([100, 101, 1000, 111], 4) == 0


def test_all_included():
    assert add_elements([1, 22, -33, 0, 99, -99], 6) == 1 + 22 - 33 + 0 + 99 - 99


# ---- property-based tests ----

@given(st.lists(st.integers(min_value=-10000, max_value=10000), min_size=1, max_size=20))
def test_equivalence_to_abs_reference_full_slice(arr):
    k = len(arr)
    assert add_elements(arr, k) == ref(arr, k)


@given(
    st.lists(st.integers(min_value=-10000, max_value=10000), min_size=1, max_size=15),
    st.data(),
)
def test_equivalence_to_abs_reference_any_valid_k(arr, data):
    k = data.draw(st.integers(min_value=1, max_value=len(arr)))
    assert add_elements(arr, k) == ref(arr, k)


@given(st.lists(st.integers(min_value=-10000, max_value=10000), min_size=1, max_size=15),
       st.data())
def test_first_k_slicing_property(arr, data):
    k = data.draw(st.integers(min_value=1, max_value=len(arr)))
    # elements beyond k must not affect result
    suffix = data.draw(st.lists(st.integers(min_value=-10000, max_value=10000), min_size=0, max_size=5))
    extended = arr + suffix
    assert add_elements(extended, k) == ref(arr, k)


@given(st.lists(st.integers(min_value=100, max_value=10000), min_size=1, max_size=10))
def test_all_large_positive_excluded(arr):
    assert add_elements(arr, len(arr)) == 0


@given(st.lists(st.integers(min_value=-10000, max_value=-100), min_size=1, max_size=10))
def test_all_large_negative_magnitude_excluded(arr):
    # abs(x) >= 100 => at least 3 digits => excluded
    assert add_elements(arr, len(arr)) == 0


@given(st.lists(st.integers(min_value=-99, max_value=99), min_size=1, max_size=10))
def test_all_small_included_equals_plain_sum(arr):
    assert add_elements(arr, len(arr)) == sum(arr)


@given(
    st.lists(st.integers(min_value=-10000, max_value=10000), min_size=1, max_size=15),
    st.data(),
)
def test_monotonicity_of_k_with_nonnegative_small(arr, data):
    # restrict to non-negative small values: extending k can only increase sum
    small = [abs(x) % 100 for x in arr]  # all in [0, 99]
    k1 = data.draw(st.integers(min_value=1, max_value=len(small)))
    k2 = data.draw(st.integers(min_value=1, max_value=len(small)))
    assume(k1 <= k2)
    assert add_elements(small, k1) <= add_elements(small, k2)


@given(st.integers(min_value=-999, max_value=-100))
def test_negative_three_digit_singleton_always_zero(x):
    assert add_elements([x], 1) == 0


@given(st.integers(min_value=100, max_value=999))
def test_positive_three_digit_singleton_always_zero(x):
    assert add_elements([x], 1) == 0


@given(st.integers(min_value=-99, max_value=99))
def test_two_digit_singleton_identity(x):
    assert add_elements([x], 1) == x
